// FUSE Relight RL-5.4: the hash-grid radiance cache on the GPU (see radiance_cache_gpu.hpp).
#include <fuse/relight/render/pathtrace/radiance_cache_gpu.hpp>

#include <fuse/renderer/vk/allocator.hpp>
#include <fuse/renderer/vk/device.hpp>

#include <algorithm>
#include <cstring>

#if defined(FUSE_VULKAN_BACKEND)
#include <vulkan/vulkan.h>

// Generated by radiance_cache/radiance_cache_embed.cmake: kRlRadianceCache{Slang,Glsl}Spv,
// FUSE_RL_RADIANCE_CACHE_{SLANG,GLSL}.
#include "rl_radiance_cache_spv.h"
#endif

namespace fuse::relight::render::pathtrace {

namespace rr = fuse::renderer;
namespace rg = fuse::renderer::rg;

namespace {
constexpr u32 kGroup = 64u;
constexpr u32 kMaxGroupsX = 32768u;
constexpr u64 kSlotStride = 256u; ///< ring slot: table / records addresses, pad, RcParams at byte 32
constexpr u64 kHeaderBytes = u64(kRcHeaderWords) * 4u;

u64 align256(u64 v) { return (v + 255u) & ~u64{255u}; }

u32 storageUsage() {
    return static_cast<u32>(rr::BufferUsage::Storage) | static_cast<u32>(rr::BufferUsage::ShaderDeviceAddress) |
           static_cast<u32>(rr::BufferUsage::TransferSrc);
}

enum StageId : u32 { kStageClear = 0u, kStageTrain = 1u, kStageUpdate = 2u, kStageResolve = 3u, kStageProbe = 4u };
} // namespace

RadianceCacheGpu::RadianceCacheGpu() = default;
RadianceCacheGpu::~RadianceCacheGpu() { destroy(); }

bool RadianceCacheGpu::init(const RadianceCacheGpuDesc& desc) {
    destroy();
    m_desc = desc;
#if defined(FUSE_VULKAN_BACKEND)
    if (desc.device == nullptr || desc.allocator == nullptr || desc.bindless == nullptr || desc.framesInFlight == 0u ||
        desc.framesInFlight > kMaxSlots) {
        m_reason = "incomplete RadianceCacheGpuDesc";
        return false;
    }
    m_retired.reserve(16);
    m_initialized = true;
    if (!createPipeline()) {
        m_reason = "no radiance cache kernel of the requested language / pipeline creation failed";
        destroy();
        return false;
    }
    m_reason = "ok";
    return true;
#else
    m_reason = "stub backend";
    return false;
#endif
}

void RadianceCacheGpu::destroy() {
    if (!m_initialized) {
        return;
    }
#if defined(FUSE_VULKAN_BACKEND)
    collectRetired(~0ull);
    for (rr::Buffer* b : {&m_table, &m_records, &m_probe, &m_ring}) {
        if (b->handle != nullptr) {
            m_desc.allocator->destroyBuffer(*b);
        }
        *b = rr::Buffer{};
    }
    const VkDevice device = static_cast<VkDevice>(m_desc.device->nativeHandle());
    if (m_pipeline != nullptr) {
        vkDestroyPipeline(device, static_cast<VkPipeline>(m_pipeline), nullptr);
    }
    if (m_layoutHandle != nullptr) {
        vkDestroyPipelineLayout(device, static_cast<VkPipelineLayout>(m_layoutHandle), nullptr);
    }
#endif
    m_pipeline = nullptr;
    m_layoutHandle = nullptr;
    m_retired.clear();
    m_tableBytes = 0;
    m_recordBytes = 0;
    m_capacity = 0;
    m_tiles = 0;
    m_width = 0;
    m_height = 0;
    m_frameIndex = 0;
    m_needsClear = true;
    m_frameReady = false;
    m_language = "none";
    m_stats = RadianceCacheGpuStats{};
    m_initialized = false;
}

bool RadianceCacheGpu::createPipeline() {
#if defined(FUSE_VULKAN_BACKEND)
    const u32* words = nullptr;
    usize bytes = 0;
#if defined(FUSE_RL_RADIANCE_CACHE_SLANG)
    if (m_desc.language == PtKernelLanguage::Auto || m_desc.language == PtKernelLanguage::Slang) {
        words = kRlRadianceCacheSlangSpv;
        bytes = sizeof(kRlRadianceCacheSlangSpv);
        m_language = "slang";
    }
#endif
#if defined(FUSE_RL_RADIANCE_CACHE_GLSL)
    if (words == nullptr && (m_desc.language == PtKernelLanguage::Auto || m_desc.language == PtKernelLanguage::Glsl)) {
        words = kRlRadianceCacheGlslSpv;
        bytes = sizeof(kRlRadianceCacheGlslSpv);
        m_language = "glsl";
    }
#endif
    if (words == nullptr) {
        return false;
    }
    const VkDevice device = static_cast<VkDevice>(m_desc.device->nativeHandle());
    VkDescriptorSetLayout setLayout = static_cast<VkDescriptorSetLayout>(m_desc.bindless->layoutHandle());
    VkPushConstantRange range{VK_SHADER_STAGE_COMPUTE_BIT, 0, static_cast<u32>(sizeof(Push))};
    VkPipelineLayoutCreateInfo layoutInfo{};
    layoutInfo.sType = VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO;
    layoutInfo.setLayoutCount = 1u;
    layoutInfo.pSetLayouts = &setLayout;
    layoutInfo.pushConstantRangeCount = 1;
    layoutInfo.pPushConstantRanges = &range;
    VkPipelineLayout layout = VK_NULL_HANDLE;
    if (vkCreatePipelineLayout(device, &layoutInfo, nullptr, &layout) != VK_SUCCESS) {
        return false;
    }
    m_layoutHandle = layout;
    VkShaderModuleCreateInfo moduleInfo{};
    moduleInfo.sType = VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO;
    moduleInfo.codeSize = bytes;
    moduleInfo.pCode = words;
    VkShaderModule module = VK_NULL_HANDLE;
    if (vkCreateShaderModule(device, &moduleInfo, nullptr, &module) != VK_SUCCESS) {
        return false;
    }
    VkComputePipelineCreateInfo info{};
    info.sType = VK_STRUCTURE_TYPE_COMPUTE_PIPELINE_CREATE_INFO;
    info.flags = static_cast<VkPipelineCreateFlags>(m_desc.bindless->pipelineCreateFlags());
    info.stage.sType = VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO;
    info.stage.stage = VK_SHADER_STAGE_COMPUTE_BIT;
    info.stage.module = module;
    info.stage.pName = "main";
    info.layout = layout;
    VkPipeline pipeline = VK_NULL_HANDLE;
    const VkResult result = vkCreateComputePipelines(device, VK_NULL_HANDLE, 1, &info, nullptr, &pipeline);
    vkDestroyShaderModule(device, module, nullptr);
    m_pipeline = pipeline;
    return result == VK_SUCCESS;
#else
    return false;
#endif
}

bool RadianceCacheGpu::ensureBuffer(rr::Buffer& buffer, u64 bytes, u32 memory, const char* name, u8* queue) {
    if (buffer.handle != nullptr && bytes <= buffer.desc.size) {
        return true;
    }
    rr::BufferDesc d{};
    d.size = static_cast<usize>(bytes);
    d.usage = static_cast<rr::BufferUsage>(storageUsage());
    d.memoryUsage = static_cast<rr::MemoryUsage>(memory);
    d.name = name;
    rr::Buffer fresh{};
    if (!m_desc.allocator->createBuffer(d, fresh) || fresh.mapped == nullptr || fresh.deviceAddress == 0u) {
        if (fresh.handle != nullptr) {
            m_desc.allocator->destroyBuffer(fresh);
        }
        return false;
    }
    if (buffer.handle != nullptr) {
        m_retired.push_back(Retired{buffer, m_frameSerial});
        ++m_stats.reallocations;
    }
    buffer = fresh;
    if (queue != nullptr) {
        *queue = rg::kNoQueue;
    }
    return true;
}

bool RadianceCacheGpu::beginFrame(u64 frameSerial, const PtCompiledScene& scene, const PtFrameDesc& frame,
                                  const RadianceCacheSettings& settings) {
    m_frameReady = false;
    if (!m_initialized || !scene.valid() || frame.width == 0u || frame.height == 0u) {
        return false;
    }
    m_frameSerial = frameSerial;
    m_stats.passes = 0;
    m_width = frame.width;
    m_height = frame.height;
    // Params (the camera from the path tracer's params of this frame).
    Word pt[kPtParamWords];
    scene.packParams(frame.settings, frame.width, frame.height, frame.frameSeed, frame.sampleBase, pt);
    packRadianceCacheParams(settings, pt, m_frameIndex, m_params);
    ++m_frameIndex;
    const u32 capacity = static_cast<u32>(m_params[1].w);
    m_tiles = radianceCacheTiles(settings, frame.width, frame.height);
    // Persistent buffers: the table (a capacity change clears it) and the records.
    const u64 tableBytes = kHeaderBytes + u64(capacity) * kRcSlotWords * 4u;
    const u64 recordBytes = u64(m_tiles) * kRcMaxVertices * kRcRecordWords * 16u;
    const bool hadTable = m_table.handle != nullptr;
    const u64 tableSize = hadTable ? m_table.desc.size : 0u;
    // + 256: the table starts at the first 256-byte aligned address of the buffer (PtParams carries address >> 8).
    if (!ensureBuffer(m_table, align256(tableBytes) + 256u, static_cast<u32>(rr::MemoryUsage::GpuToCpu),
                      "relight.radiance_cache.table", &m_tableQueue) ||
        !ensureBuffer(m_records, align256(recordBytes), static_cast<u32>(rr::MemoryUsage::GpuToCpu),
                      "relight.radiance_cache.records", &m_recordsQueue)) {
        m_reason = "radiance cache buffers";
        return false;
    }
    if (m_probeEnabled && !ensureBuffer(m_probe, align256(u64(m_tiles) * kRcMaxVertices * 16u),
                                        static_cast<u32>(rr::MemoryUsage::GpuToCpu), "relight.radiance_cache.probe",
                                        &m_probeQueue)) {
        m_reason = "radiance cache probe buffer";
        return false;
    }
    if (!hadTable || m_table.desc.size != tableSize || capacity != m_capacity) {
        m_needsClear = true;
    }
    m_capacity = capacity;
    m_tableBytes = tableBytes;
    m_tableOffset = align256(m_table.deviceAddress) - m_table.deviceAddress;
    m_recordBytes = recordBytes;
    if (m_ring.handle == nullptr &&
        !ensureBuffer(m_ring, kSlotStride * m_desc.framesInFlight, static_cast<u32>(rr::MemoryUsage::CpuToGpu),
                      "relight.radiance_cache.ring", &m_ringQueue)) {
        m_reason = "radiance cache ring";
        return false;
    }
    m_blockOffset = u64(frameSerial % m_desc.framesInFlight) * kSlotStride;
    u8* slot = static_cast<u8*>(m_ring.mapped) + m_blockOffset;
    const u64 block[3] = {tableAddress(), m_records.deviceAddress,
                          m_probeEnabled ? m_probe.deviceAddress : u64{0}};
    std::memcpy(slot, block, sizeof(block));
    std::memcpy(slot + 32u, m_params, sizeof(m_params));
    m_frameReady = true;
    ++m_stats.frames;
    return true;
}

bool RadianceCacheGpu::addPasses(rg::Graph& graph, PathTracerGpu& pt, const PtGraphRefs& ptRefs) {
    if (!m_initialized || !m_frameReady || !ptRefs.valid) {
        return false;
    }
    if (!pt.addLightsPass(graph, ptRefs)) {
        m_reason = "light convert pass";
        return false;
    }
    const PtTraceBindings b = pt.traceBindings();
    if (b.width != m_width || b.height != m_height || b.params == 0u) {
        m_reason = "PathTracerGpu frame does not match";
        return false;
    }
    m_refs = RadianceCacheGraphRefs{};
    m_refs.table = graph.importBuffer(rg::ImportedBuffer{m_table.handle, m_table.desc.size, m_tableQueue,
                                                         &m_tableQueue, "relight.radiance_cache.table"});
    m_refs.records = graph.importBuffer(rg::ImportedBuffer{m_records.handle, m_records.desc.size, m_recordsQueue,
                                                           &m_recordsQueue, "relight.radiance_cache.records"});
    if (m_probeEnabled && m_probe.handle != nullptr) {
        m_refs.probe = graph.importBuffer(rg::ImportedBuffer{m_probe.handle, m_probe.desc.size, m_probeQueue,
                                                             &m_probeQueue, "relight.radiance_cache.probe"});
    }
    m_refs.ring = graph.importBuffer(
        rg::ImportedBuffer{m_ring.handle, m_ring.desc.size, m_ringQueue, &m_ringQueue, "relight.radiance_cache.ring"});
    m_refs.ringRange = rg::BufferRange{m_blockOffset, 112u};
    m_refs.valid = true;

    Push base{};
    base.params = b.params;
    base.instances = b.instances;
    base.triangles = b.triangles;
    base.materials = b.materials;
    base.portals = b.portals;
    base.lightMap = b.lightMap;
    base.lightTable = ptRefs.lights.tableAddress;
    base.lightTree = ptRefs.lights.tree.header;
    base.tlas = b.tlas;
    base.lut = b.lut;
    base.block = m_ring.deviceAddress + m_blockOffset;
    base.width = m_width;
    base.height = m_height;
    base.lightCount = b.lightCount;
    const rg::BufferRange tableAll{m_tableOffset, m_tableBytes};
    const rg::BufferRange header{m_tableOffset, kHeaderBytes};
    const rg::BufferRange records{0u, m_recordBytes};
    u32 count = 0;
    auto add = [&](const char* name, u32 stage, u32 items) -> rg::PassBuilder {
        PassRecord& r = m_passes[count++];
        r = PassRecord{};
        r.self = this;
        r.push = base;
        r.push.stage = stage;
        r.push.count = items;
        const u32 groups = std::max((items + kGroup - 1u) / kGroup, 1u);
        r.groupsX = std::min(groups, kMaxGroupsX);
        r.groupsY = (groups + r.groupsX - 1u) / r.groupsX;
        r.push.pitch = r.groupsX * kGroup;
        ++m_stats.passes;
        rg::PassBuilder pass = graph.addPass(name, &RadianceCacheGpu::record, &r);
        pass.use(m_refs.ring, rg::Access::StorageRead, m_refs.ringRange, rg::kStageCompute);
        return pass;
    };
    if (m_needsClear) {
        rg::PassBuilder p = add("relight.radiance_cache.clear", kStageClear, m_capacity);
        p.use(m_refs.table, rg::Access::StorageWrite, tableAll, rg::kStageCompute);
        m_needsClear = false;
        ++m_stats.clears;
    }
    {
        rg::PassBuilder p = add("relight.radiance_cache.train", kStageTrain, m_tiles);
        p.use(ptRefs.ring, rg::Access::StorageRead, ptRefs.ringRange, rg::kStageCompute)
            .use(ptRefs.rt.tlas, rg::Access::AccelerationStructureRead, {}, rg::kStageCompute)
            .use(ptRefs.statics, rg::Access::StorageRead, {}, rg::kStageCompute)
            .use(ptRefs.lights.ring, rg::Access::StorageRead, ptRefs.lights.tableRange, rg::kStageCompute)
            .use(m_refs.records, rg::Access::StorageWrite, records, rg::kStageCompute)
            .use(m_refs.table, rg::Access::StorageWrite, header, rg::kStageCompute);
        if (ptRefs.lights.tree.tree.valid()) {
            p.use(ptRefs.lights.tree.tree, rg::Access::StorageRead, ptRefs.lights.tree.range, rg::kStageCompute);
        }
    }
    {
        rg::PassBuilder p = add("relight.radiance_cache.update", kStageUpdate, m_tiles * kRcMaxVertices);
        p.use(m_refs.records, rg::Access::StorageRead, records, rg::kStageCompute)
            .use(m_refs.table, rg::Access::StorageReadWrite, tableAll, rg::kStageCompute);
    }
    {
        rg::PassBuilder p = add("relight.radiance_cache.resolve", kStageResolve, m_capacity);
        p.use(m_refs.table, rg::Access::StorageReadWrite, tableAll, rg::kStageCompute);
    }
    if (m_refs.probe.valid()) {
        rg::PassBuilder p = add("relight.radiance_cache.probe", kStageProbe, m_tiles * kRcMaxVertices);
        p.use(m_refs.records, rg::Access::StorageRead, records, rg::kStageCompute)
            .use(m_refs.table, rg::Access::StorageRead, tableAll, rg::kStageCompute)
            .use(m_refs.probe, rg::Access::StorageWrite, rg::BufferRange{0u, u64(m_tiles) * kRcMaxVertices * 16u},
                 rg::kStageCompute);
    }
    if (!pt.setRadianceCache(tableAddress(), m_refs.table, tableAll)) {
        m_reason = "PathTracerGpu::setRadianceCache (table address)";
        return false;
    }
    return true;
}

void RadianceCacheGpu::record(const rg::PassContext& context, void* user) {
#if defined(FUSE_VULKAN_BACKEND)
    const PassRecord& r = *static_cast<const PassRecord*>(user);
    const RadianceCacheGpu& self = *r.self;
    VkCommandBuffer cmd = static_cast<VkCommandBuffer>(context.commandBuffer);
    vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, static_cast<VkPipeline>(self.m_pipeline));
    self.m_desc.bindless->bind(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, self.m_layoutHandle, 0);
    vkCmdPushConstants(cmd, static_cast<VkPipelineLayout>(self.m_layoutHandle), VK_SHADER_STAGE_COMPUTE_BIT, 0,
                       static_cast<u32>(sizeof(Push)), &r.push);
    vkCmdDispatch(cmd, r.groupsX, r.groupsY, 1u);
#else
    (void)context;
    (void)user;
#endif
}

u32 RadianceCacheGpu::collectRetired(u64 completedSerial) {
    u32 collected = 0;
    usize keep = 0;
    for (usize i = 0; i < m_retired.size(); ++i) {
        if (m_retired[i].serial > completedSerial) {
            m_retired[keep++] = m_retired[i];
            continue;
        }
        if (m_retired[i].buffer.handle != nullptr) {
            m_desc.allocator->destroyBuffer(m_retired[i].buffer);
        }
        ++collected;
    }
    m_retired.resize(keep);
    return collected;
}

const u32* RadianceCacheGpu::mappedTable() const {
    return m_table.mapped != nullptr ? reinterpret_cast<const u32*>(static_cast<const u8*>(m_table.mapped) + m_tableOffset)
                                     : nullptr;
}
const Word* RadianceCacheGpu::mappedRecords() const { return static_cast<const Word*>(m_records.mapped); }
const Word* RadianceCacheGpu::mappedProbe() const { return static_cast<const Word*>(m_probe.mapped); }

} // namespace fuse::relight::render::pathtrace
